            ? "(?fsm:$c->[0]\n"
                ."  (+system (clock clk) ($c->[1] reset_pin $c->[2]))\n"
                ."  (+interface (output Q) (output Z) (output FLAG) (output SPARE))\n"
                ."  (+size (Q 5 (reset 19)) (Z 4 (reset 0)) (FLAG 1 (reset 1)) (SPARE 7))\n"
