}
subtest 'signal reset metadata does not invent a missing hardware reset' => sub {
    my $source = "$work/no_reset.fsm";
    write_file($source, "(?fsm:no_reset (+system (clock clk))\n"
        ."(+interface (output Q)) (+size (Q 5 (reset 19))) (idle (-> idle)))\n");
