            my $compile = ghdl_stage([$ghdl, '-a', '--std=08', '--workdir='.$dir, $hdl, $tb], $dir);
            ok($compile->{ok}, 'GHDL analyzes the generated actor and independent oracle') or diag($compile->{diagnostic}, $compile->{stderr});
            return unless $compile->{ok};
